assert.equal(evaluate('applyDefaultRaidOnStartup()'),false);
assert.equal(evaluate('activeTemplateName'),'Custom');
assert.equal(evaluate('fellowshipSetup.rules.length'),0);
console.log('Passed: default raid assignments applied to new plans; custom restored session remains authoritative.');
evaluate(`constraints=[];fellowshipSetup=emptyFellowshipSetup();template={Tank:[0,0],Healer:[0,0],Debuffer:[0,0],Buffer:[0,0]};size=6;players=Array.from({length:6},(_,i)=>({id:'estimate'+i,name:'E'+i,max:4,available:[true],choices:[{c:'Hunter',spec:'Red',role:'DPS',flexible:true},{c:'Champion',spec:'Red',role:'DPS',flexible:true}]}));let originalRosterForEstimate=JSON.stringify(players);`);
assert.equal(evaluate('estimateRosterRunCount()'),2);
assert.equal(evaluate('JSON.stringify(players)'),evaluate('originalRosterForEstimate'));
evaluate(`players.forEach(p=>p.choices=p.choices.slice(0,1))`);assert.equal(evaluate('estimateRosterRunCount()'),1);
evaluate(`players.forEach(p=>p.tentativeRuns=[true])`);assert.equal(evaluate('estimateRosterRunCount()'),1);
evaluate(`players.forEach(p=>{p.tentativeRuns=[false];p.choices.push({c:'Champion',spec:'Red',role:'DPS',flexible:true})});template.Healer=[1,1]`);assert.equal(evaluate('estimateRosterRunCount()'),1);
console.log('Passed: run estimate uses unique confirmed player/classes, considers roles, preserves disabled specs and excludes tentatives from automatic expansion.');
// Repeats enter only after fresh-character attempts, and later repeats cost more.
evaluate(`fellowshipSetup=emptyFellowshipSetup();constraints=[];rolePriorities={};size=1;duration=1;template={Tank:[0,0],Healer:[0,0],Debuffer:[0,0],Buffer:[0,0]};runs=Array.from({length:4},(_,i)=>({id:i+1,source:i,time:18+i,label:'Run '+(i+1)}));players=[{id:'alts',name:'Alts',max:4,available:[true,true,true,true],preferredClasses:['Hunter'],choices:[{c:'Hunter',spec:'Red',role:'DPS'},{c:'Champion',spec:'Red',role:'DPS'},{c:'Warden',spec:'Red',role:'DPS'},{c:'Burglar',spec:'Red',role:'DPS'}]}];teams=assign(runs);`);
assert.equal(evaluate('lockedPlayerCount(teams)'),0);
assert.equal(evaluate('teams.every(t=>t.members.length===1)'),true);
assert(evaluate('repeatedCharacterCost(3)>repeatedCharacterCost(2)&&repeatedCharacterCost(2)>repeatedCharacterCost(1)'));
evaluate(`players=[{id:'required',name:'Required',max:4,available:[true,true,true,true],choices:[{c:'Minstrel',spec:'Blue',role:'Healer'}]}];template.Healer=[1,1];teams=assign(runs);`);
assert.equal(evaluate('teams.every(t=>t.members.length===1&&t.members[0].role===\"Healer\")'),true);
evaluate(`template.Healer=[0,0];let seqMember=id=>({id,name:id,c:'Hunter',spec:'Red',role:'DPS',available:[true,true,true,true],choices:[{c:'Hunter',spec:'Red',role:'DPS'}]});players=[seqMember('x'),seqMember('y')];let concentrated=runs.map(t=>({...t,members:[seqMember('x')]}));let spread=runs.map((t,i)=>({...t,members:[seqMember(i%2?'y':'x')]}));`);
assert(evaluate('betterSchedule(scheduleObjective(spread),scheduleObjective(concentrated))'));
console.log('Passed: fresh alts before preferred repeats, required repeat fallback, increasing repeat costs and distributed unavoidable locks.');
